/**
 * Phase 9 — Centralized financial calculation utilities (spec G/J).
 *
 * Pure, dependency-free functions used by every portfolio surface so the same
 * math cannot drift between components. They mirror the backend engine
 * (`portfolio_engine.py`) exactly — same fee treatment, same clamping rules,
 * same rounding — so local preview and server numbers agree.
 *
 * All functions are NaN-safe: an invalid input produces `null`/`false`,
 * never a fabricated number.
 */

export type Side = "BUY" | "SELL";

/** Spec F: Transaction shape. `id` is generated by storage; `userId` is
 * auth-ready (always null until authenticated persistence lands). */
export interface Transaction {
  id: string;
  userId: string | null;
  symbol: string;
  side: Side;
  quantity: number;
  price: number;
  date: string; // ISO timestamp
  fees: number;
  notes?: string;
  broker?: string;
}

/** Raw form values before validation — everything is a string here. */
export interface TransactionInput {
  symbol: string;
  side: Side;
  quantity: string;
  price: string;
  fees: string;
  date: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: Record<string, string>;
}

/** Spec G: the shape of one open position. */
export interface Position {
  symbol: string;
  quantity: number;
  averageCost: number; // per share, fees included
  investedCapital: number; // total cost of the OPEN position, fees included
  realizedPnl: number; // cumulative from closed portions
  totalInvestedAllTime: number; // open cost + cost basis of everything sold
}

export interface PnlResult {
  amount: number | null; // absolute PKR
  percent: number | null; // %
}

/** Quantity held for a symbol right now, and realized P&L so far. */
export function calculateQuantityAndRealized(
  transactions: Transaction[],
  symbol: string
): { quantity: number; realizedPnl: number; totalSoldCost: number } {
  const rows = transactions
    .filter((t) => t.symbol === symbol)
    .sort((a, b) => a.date.localeCompare(b.date));

  let quantity = 0;
  let costBasisOpen = 0;
  let realizedPnl = 0;
  let totalSoldCost = 0;

  for (const t of rows) {
    if (t.side === "BUY") {
      quantity += t.quantity;
      costBasisOpen += t.quantity * t.price + t.fees;
    } else {
      // Never allow a negative holding (spec H): clamp the sell to holdings.
      const sellQty = Math.min(t.quantity, quantity);
      if (sellQty <= 0) continue;
      const avg = quantity > 0 ? costBasisOpen / quantity : 0;
      realizedPnl += sellQty * t.price - t.fees - sellQty * avg;
      costBasisOpen -= sellQty * avg;
      quantity -= sellQty;
      totalSoldCost += sellQty * avg;
      if (Math.abs(quantity) < 1e-9) {
        quantity = 0;
        costBasisOpen = 0;
      }
    }
  }
  return { quantity, realizedPnl, totalSoldCost };
}

/** Spec H: average cost derived from valid BUYs + position state. */
export function calculateAverageCost(transactions: Transaction[], symbol: string): number {
  const pos = calculatePosition(transactions, symbol);
  return pos ? pos.averageCost : 0;
}

/** Spec G: one open position from transactions. */
export function calculatePosition(transactions: Transaction[], symbol: string): Position | null {
  const rows = transactions
    .filter((t) => t.symbol === symbol)
    .sort((a, b) => a.date.localeCompare(b.date));

  let quantity = 0;
  let costBasisOpen = 0;
  let realizedPnl = 0;
  let totalInvestedAllTime = 0;

  for (const t of rows) {
    if (t.side === "BUY") {
      quantity += t.quantity;
      const buyCost = t.quantity * t.price + t.fees;
      costBasisOpen += buyCost;
      totalInvestedAllTime += buyCost;
    } else {
      const sellQty = Math.min(t.quantity, quantity);
      if (sellQty <= 0) continue;
      const avg = quantity > 0 ? costBasisOpen / quantity : 0;
      realizedPnl += sellQty * t.price - t.fees - sellQty * avg;
      costBasisOpen -= sellQty * avg;
      quantity -= sellQty;
      if (Math.abs(quantity) < 1e-9) {
        quantity = 0;
        costBasisOpen = 0;
      }
    }
  }

  if (quantity <= 0) return null;
  return {
    symbol,
    quantity,
    averageCost: costBasisOpen / quantity,
    investedCapital: costBasisOpen,
    realizedPnl,
    totalInvestedAllTime,
  };
}

/** Spec G: invested capital for the open position. */
export function calculateInvestedCapital(transactions: Transaction[], symbol: string): number {
  return calculatePosition(transactions, symbol)?.investedCapital ?? 0;
}

/** Spec I: market value = current price × quantity. Unpriced -> null. */
export function calculateMarketValue(
  position: Position,
  currentPrice: number | null
): number | null {
  if (currentPrice === null || !Number.isFinite(currentPrice) || currentPrice <= 0) return null;
  return position.quantity * currentPrice;
}

/** Spec J: unrealized P&L in PKR and %. */
export function calculateUnrealizedPnl(
  position: Position,
  currentPrice: number | null
): PnlResult {
  const mv = calculateMarketValue(position, currentPrice);
  if (mv === null) return { amount: null, percent: null };
  const amount = mv - position.investedCapital;
  const percent = position.investedCapital > 0 ? (amount / position.investedCapital) * 100 : 0;
  return { amount, percent };
}

/** Spec J: realized P&L (from the position's closed portions). */
export function calculateRealizedPnl(transactions: Transaction[], symbol: string): number {
  return calculateQuantityAndRealized(transactions, symbol).realizedPnl;
}

/** Spec G: total return = realized + unrealized, absolute and %. */
export function calculateTotalReturn(
  position: Position,
  currentPrice: number | null
): PnlResult {
  const unrealized = calculateUnrealizedPnl(position, currentPrice);
  const amount =
    unrealized.amount === null ? null : position.realizedPnl + unrealized.amount;
  const base = position.totalInvestedAllTime;
  const percent = amount !== null && base > 0 ? (amount / base) * 100 : null;
  return { amount, percent };
}

/** Spec K: portfolio dashboard metrics over all open positions. */
export interface PortfolioSummaryMetrics {
  totalInvested: number;
  currentValue: number;
  unrealizedPnl: number | null;
  realizedPnl: number;
  totalPnl: number | null;
  totalReturnPct: number | null;
  positions: number;
  pricedPositions: number;
}

export function calculatePortfolioSummary(
  transactions: Transaction[],
  prices: Record<string, number | null>
): { positions: Position[]; summary: PortfolioSummaryMetrics } {
  const symbols = [...new Set(transactions.map((t) => t.symbol))];
  const positions = symbols
    .map((s) => calculatePosition(transactions, s))
    .filter((p): p is Position => p !== null);

  let totalInvested = 0;
  let currentValue = 0;
  let realizedPnl = 0;
  let unrealizedPnl = 0;
  let pricedPositions = 0;
  let allPriced = true;

  for (const p of positions) {
    totalInvested += p.investedCapital;
    realizedPnl += p.realizedPnl;
    const price = prices[p.symbol] ?? null;
    const mv = calculateMarketValue(p, price);
    if (mv === null) {
      allPriced = false;
      continue;
    }
    pricedPositions += 1;
    currentValue += mv;
    unrealizedPnl += mv - p.investedCapital;
  }

  const totalPnl = allPriced ? realizedPnl + unrealizedPnl : realizedPnl;
  return {
    positions,
    summary: {
      totalInvested,
      currentValue,
      unrealizedPnl: allPriced ? unrealizedPnl : null,
      realizedPnl,
      totalPnl,
      totalReturnPct:
        allPriced && totalInvested > 0 ? (totalPnl / totalInvested) * 100 : null,
      positions: positions.length,
      pricedPositions,
    },
  };
}

/**
 * Spec N — validation. Rejects: negative/zero quantity, invalid price,
 * invalid/missing date, invalid symbol, negative fees, and SELL > holdings.
 * Returns per-field error messages ready to render.
 */
export function validateTransactionInput(
  input: TransactionInput,
  availableQuantity: number
): ValidationResult {
  const errors: Record<string, string> = {};

  const symbol = input.symbol.trim().toUpperCase();
  if (!symbol) {
    errors.symbol = "Symbol is required";
  } else if (!/^[A-Z0-9.^=-]{1,15}$/.test(symbol)) {
    errors.symbol = "Invalid symbol format";
  }

  const quantity = Number(input.quantity);
  if (input.quantity.trim() === "" || Number.isNaN(quantity)) {
    errors.quantity = "Quantity is required";
  } else if (!Number.isFinite(quantity)) {
    errors.quantity = "Quantity must be a finite number";
  } else if (quantity <= 0) {
    errors.quantity = quantity < 0 ? "Quantity cannot be negative" : "Quantity cannot be zero";
  }

  const price = Number(input.price);
  if (input.price.trim() === "" || Number.isNaN(price)) {
    errors.price = "Price is required";
  } else if (!Number.isFinite(price)) {
    errors.price = "Price must be a finite number";
  } else if (price <= 0) {
    errors.price = price < 0 ? "Price cannot be negative" : "Price must be greater than 0";
  }

  const fees = input.fees.trim() === "" ? 0 : Number(input.fees);
  if (Number.isNaN(fees) || !Number.isFinite(fees)) {
    errors.fees = "Fees must be a number";
  } else if (fees < 0) {
    errors.fees = "Fees cannot be negative";
  }

  if (!input.date) {
    errors.date = "Date is required";
  } else {
    const d = new Date(input.date);
    if (Number.isNaN(d.getTime())) {
      errors.date = "Invalid date";
    } else if (d.getTime() > Date.now() + 5 * 60 * 1000) {
      errors.date = "Date cannot be in the future";
    }
  }

  if (input.side === "SELL" && !errors.quantity && availableQuantity < quantity) {
    errors.quantity = `SELL exceeds available holdings — you hold ${formatQty(availableQuantity)}`;
  }

  return { valid: Object.keys(errors).length === 0, errors };
}

function formatQty(q: number): string {
  return Number.isInteger(q) ? String(q) : q.toFixed(4).replace(/0+$/, "").replace(/\.$/, "");
}

// ---------------------------------------------------------------------------
// formatting helpers (PKR)
// ---------------------------------------------------------------------------

export function formatPkr(amount: number | null, digits = 2): string {
  if (amount === null || !Number.isFinite(amount)) return "—";
  return `PKR ${amount.toLocaleString("en-US", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits,
  })}`;
}

export function formatPct(pct: number | null, showSign = true): string {
  if (pct === null || !Number.isFinite(pct)) return "—";
  const sign = pct > 0 && showSign ? "+" : "";
  return `${sign}${pct.toFixed(2)}%`;
}

export function formatQtyDisplay(q: number): string {
  return Number.isInteger(q) ? q.toLocaleString("en-US") : q.toLocaleString("en-US", { maximumFractionDigits: 4 });
}
